 39	def order_svg():
 40	    """듣는 순서 도해. 도형과 글자만 (자가 벡터 허용 범위). 응시와 세트 해설 사이 되돌이 화살표가 30세트 사이클."""
 41	    def node(x, k, t, sub):
 42	        return (f'<rect x="{x}" y="34" width="144" height="64" rx="4"/>'
 43	                f'<text class="k" x="{x+12}" y="52">{k}</text><text x="{x+12}" y="72">{t}</text><text class="sub" x="{x+12}" y="89">{sub}</text>')
 44	    arrow = lambda x: f'<path d="M{x} 66h20m-6-5 6 5-6 5" />'
 45	    return ('<svg class="order" viewBox="0 0 672 132" role="img" aria-label="듣는 순서. 공통 풀이 4편, 단위 강의, 응시, 세트 해설, 그리고 다시 응시. 응시와 세트 해설을 지문마다 반복한다" xmlns="http://www.w3.org/2000/svg">'
 46	            '<g fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round">'
