 66	def by_kind(code):
 67	    return {"unit": [l for l in LECS if l["kind"] == "unit" and l["unit_code"] == code],
 68	            "passage": [l for l in LECS if l["kind"] == "passage" and l["unit_code"] == code],
 69	            "common": [l for l in LECS if l["kind"] == "common"]}
 70	
 71	
 72	def courses():
 73	    out = []
 74	    for code in ORDER:
 75	        u = UNITS[code]; k = by_kind(code)
 76	        n = len(k["common"]) + len(k["unit"]) + len(k["passage"])
 77	        sec = sum((l["duration_sec"] or 0) for g in k.values() for l in g)
 78	        out.append({"code": code, "label": u["label"], "univ": UNIV[code], "track": TRACK[code], "sku": u["sku"], "price": u["price"],
 79	                    "single": u["single_price"], "set_count": u["set_count"], "n": n, "sec": sec, "k": k, "spec": SPEC[code]})
 80	    k = by_kind(None)
 81	    k["unit"], k["passage"] = [], []
 82	    sec = sum((l["duration_sec"] or 0) for l in k["common"])
 83	    out.append({"code": "common", "label": COMMON_TX, "univ": "common", "track": "common", "sku": "lecture-common", "price": 220000, "single": None,
 84	                "set_count": 0, "n": len(k["common"]), "sec": sec, "k": k, "spec": "다섯 단위 공통"})
 85	    return out
